def set_backend(self, backend: BackendV2) -> None:
        """Set backend for simulation.
        This method changes noise_model, coupling_map, basis_gates according to given backend.

        Args:
            backend: backend to be set.

        Raises:
            MissingOptionalLibraryError: if qiskit-aer is not found.
        """
        if not optionals.HAS_AER:
            raise MissingOptionalLibraryError(
                "qiskit-aer", "Aer provider", "pip install qiskit-aer"
            )
        from qiskit_aer.noise import (
            NoiseModel as AerNoiseModel,
        )
        self.noise_model = AerNoiseModel.from_backend(backend)
        if isinstance(backend, BackendV2):
            self.coupling_map = backend.coupling_map
            self.basis_gates = backend.operation_names

def faulty_qubits(self) -> list:
        """Return a list of faulty qubits."""
        faulty = []
        for qubit in self._qubits:
            if not self.is_qubit_operational(qubit):
                faulty.append(qubit)
        return faulty

def _iter_all_fields(
    data_cls: Any, indent: int = 0, dict_form: dict | None = None
) -> Iterable[tuple[int, str, Any, bool]]:
    # we pass dict_form through recursion simply to avoid calling asdict() more than once
    dict_form = dict_form or asdict(data_cls)
    suboptions = []
    for name, val in dict_form.items():
        if is_dataclass(subopt := getattr(data_cls, name)):
            suboptions.append((name, subopt))
        elif name != "_VERSION":
            yield (indent, name, val, False)
    for name, subopt in suboptions:
        yield (indent, name, subopt, True)
        yield from _iter_all_fields(subopt, indent + 1, dict_form[name])

def _discover_backends_from_instance(self, instance: str) -> list[str]:
        """Retrieve all backends from the given instance."""
        try:
            if instance != self._active_api_client._instance:
                if instance in self._api_clients:
                    self._active_api_client = self._api_clients[instance]
                else:
                    new_client = self._create_new_cloud_api_client(instance)
                    self._api_clients.update({instance: new_client})
                    self._active_api_client = new_client
            self._backends_list = self._active_api_client.list_backends()
            return [backend["name"] for backend in self._backends_list]
        except Exception:
            logger.warning("Invalid instance %s", instance)
            return []

