def _update_options(old: dict, new: dict) -> None:
        if not new:
            return
        for key, val in old.items():
            if key in new.keys():
                if isinstance(val, dict):
                    _update_options(val, new.pop(key))
                else:
                    old[key] = new.pop(key)
        # Add new keys.
        for key in list(new.keys()):
            old[key] = new.pop(key)

